// Java and Python reference solutions as plain files (plan 0063). Files: packages/shared/content/solutions/<problem-id>.java|.py
//   pnpm solutions:build              write packages/shared/src/judge/generated/solutions.ts (only the lead runs this, at the end)
//   pnpm solutions:check              fail when the generated file is stale or a file name is not a problem id / .java / .py
//   pnpm solutions:status [group]     done/total per language for groups d, e, f, and the missing ids
//   pnpm solutions:todo <group> [--limit 10]   the next problems without both files: starters and the C++ reference
// Rules and examples: docs/solutions.md. The file helpers are pure (no TypeScript imports) so a test can use them.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const SOLUTIONS_DIR = path.join(root, "packages/shared/content/solutions");
export const GENERATED_FILE = path.join(root, "packages/shared/src/judge/generated/solutions.ts");
export const SKIP_STRESS_LINE = "# verify: skip-stress";
const EXT = { ".java": "java", ".py": "python" };
const EXT_BRUTE = { ".cpp": "cpp", ".java": "java", ".py": "python" };

/**
 * Reads the solution folder.
 * @returns {{
 *   files: { id: string; lang: "java" | "python"; name: string; code: string }[];
 *   bruteFiles: { id: string; lang: "cpp" | "java" | "python"; name: string; code: string }[];
 *   errors: string[];
 * }}
 */
export function readSolutionFiles(dir = SOLUTIONS_DIR) {
  const files = [];
  const bruteFiles = [];
  const errors = [];
  if (!fs.existsSync(dir)) return { files, bruteFiles, errors };
  for (const name of fs.readdirSync(dir).sort()) {
    if (name === "README.md") continue;
    const full = path.join(dir, name);
    if (!fs.statSync(full).isFile()) {
      errors.push(`${name}: only files are allowed in the solutions folder`);
      continue;
    }
    const ext = path.extname(name);
    if (name.includes(".brute.")) {
      const lang = EXT_BRUTE[ext];
      if (!lang) {
        errors.push(`${name}: brute extension must be .cpp, .java or .py`);
        continue;
      }
      const id = name.slice(0, -(`.brute${ext}`.length));
      bruteFiles.push({ id, lang, name, code: fs.readFileSync(full, "utf8").replace(/\r\n?/g, "\n") });
    } else {
      const lang = EXT[ext];
      if (!lang) {
        errors.push(`${name}: extension must be .java or .py`);
        continue;
      }
      const id = name.slice(0, -ext.length);
      files.push({ id, lang, name, code: fs.readFileSync(full, "utf8").replace(/\r\n?/g, "\n") });
    }
  }
  return { files, bruteFiles, errors };
}

/** The generated TypeScript for the given files. Deterministic: sorted by id, java before python. */
export function renderGenerated(files, bruteFiles = []) {
  /** @type {Record<string, { java?: string; python?: string }>} */
  const by = {};
  for (const f of files) (by[f.id] ??= {})[f.lang] = f.code;
  const ids = Object.keys(by).sort();
  const head = `// Generated by scripts/solutions.mjs from packages/shared/content/solutions/. Do not edit; run \`pnpm solutions:build\`.\nexport const SOLUTIONS: Record<string, { java?: string; python?: string }> = `;
  
  let solutionsPart = `${head}{};\n`;
  if (ids.length) {
    const rows = ids.map((id) => {
      const parts = ["java", "python"].filter((l) => by[id][l] !== undefined).map((l) => `${l}: ${JSON.stringify(by[id][l])}`);
      return `  ${JSON.stringify(id)}: { ${parts.join(", ")} },`;
    });
    solutionsPart = `${head}{\n${rows.join("\n")}\n};\n`;
  }

  /** @type {Record<string, { cpp?: string; java?: string; python?: string }>} */
  const byBrute = {};
  for (const f of bruteFiles) (byBrute[f.id] ??= {})[f.lang] = f.code;
  const bruteIds = Object.keys(byBrute).sort();
  const bruteHead = `export const BRUTE: Record<string, { cpp?: string; java?: string; python?: string }> = `;

  let brutePart = `${bruteHead}{};\n`;
  if (bruteIds.length) {
    const bruteRows = bruteIds.map((id) => {
      const parts = ["cpp", "java", "python"].filter((l) => byBrute[id][l] !== undefined).map((l) => `${l}: ${JSON.stringify(byBrute[id][l])}`);
      return `  ${JSON.stringify(id)}: { ${parts.join(", ")} },`;
    });
    brutePart = `${bruteHead}{\n${bruteRows.join("\n")}\n};\n`;
  }

  return `${solutionsPart}\n${brutePart}`;
}

/** Problems in the folder that are not known ids, plus bad extensions. */
export function checkFiles(files, folderErrors, knownIds) {
  const errors = [...folderErrors];
  for (const f of files) if (!knownIds.has(f.id)) errors.push(`${f.name}: "${f.id}" is not a problem id`);
  return errors;
}

/** True when generated/solutions.ts matches the files. */
export function generatedIsCurrent(dir = SOLUTIONS_DIR, generated = GENERATED_FILE) {
  const { files, bruteFiles, errors } = readSolutionFiles(dir);
  if (errors.length) return false;
  return fs.existsSync(generated) && fs.readFileSync(generated, "utf8").replace(/\r\n/g, "\n") === renderGenerated(files, bruteFiles);
}

/** Status of one group: ids missing Java or Python, and brute force coverage, from the files on disk. */
export function groupStatus(ids, files, bruteFiles = [], interviewBy = {}) {
  const has = { java: new Set(), python: new Set() };
  for (const f of files) has[f.lang].add(f.id);

  const hasBrute = { cpp: new Set(), java: new Set(), python: new Set() };
  for (const f of bruteFiles) hasBrute[f.lang]?.add(f.id);

  const bruteSame = new Set(ids.filter((i) => interviewBy[i]?.brute === "same"));

  return {
    total: ids.length,
    java: ids.filter((i) => has.java.has(i)).length,
    python: ids.filter((i) => has.python.has(i)).length,
    missing: ids.filter((i) => !has.java.has(i) || !has.python.has(i)),
    missingJava: ids.filter((i) => !has.java.has(i)),
    missingPython: ids.filter((i) => !has.python.has(i)),
    skipStress: files.filter((f) => f.lang === "python" && ids.includes(f.id) && f.code.split("\n")[0].trim() === SKIP_STRESS_LINE).map((f) => f.id),
    bruteSame: ids.filter((i) => bruteSame.has(i)).length,
    bruteCpp: ids.filter((i) => hasBrute.cpp.has(i) || bruteSame.has(i)).length,
    bruteJava: ids.filter((i) => hasBrute.java.has(i) || bruteSame.has(i)).length,
    brutePython: ids.filter((i) => hasBrute.python.has(i) || bruteSame.has(i)).length,
    missingBrute: ids.filter((i) => !bruteSame.has(i) && (!hasBrute.cpp.has(i) || !hasBrute.java.has(i) || !hasBrute.python.has(i))),
    missingBruteCpp: ids.filter((i) => !bruteSame.has(i) && !hasBrute.cpp.has(i)),
    missingBruteJava: ids.filter((i) => !bruteSame.has(i) && !hasBrute.java.has(i)),
    missingBrutePython: ids.filter((i) => !bruteSame.has(i) && !hasBrute.python.has(i)),
  };
}

async function loadTs() {
  const shared = await import("@habit/shared");
  const groups = await import("../packages/shared/src/judge/solution-groups.ts");
  let INTERVIEW = {};
  try {
    const itv = await import("../packages/shared/src/judge/generated/interview.ts");
    INTERVIEW = itv.INTERVIEW ?? {};
  } catch {
    /* interview generated might not be present */
  }
  return { JUDGE_PROBLEMS: shared.JUDGE_PROBLEMS, templateFor: shared.templateFor, INTERVIEW, ...groups };
}

function starter(templateFor, spec, lang) {
  try {
    const t = templateFor(spec, lang);
    if (typeof t === "string" && t.trim()) return t;
  } catch {
    /* language not supported by the templates yet */
  }
  return null;
}

function normalizeComplexity(s) {
  return (s || "")
    .toLowerCase()
    .replace(/\\(times|cdot|log|text|sigma)/g, "$1")
    .replace(/[^a-z0-9]/g, "");
}

export function auditComplexity(JUDGE_PROBLEMS, INTERVIEW) {
  const KNOWN_CASES = new Set([
    "lc-49",
    "lc-432",
    "c-euler-14",
    "c-euler-21",
    "c-euler-23",
    "c-cf-158b",
    "cses-tree-distances-i",
    "cses-tree-distances-ii",
    "cses-fixed-length-paths-i",
    "cses-path-queries-ii",
    "cses-distinct-colors",
    "cses-finding-a-centroid",
  ]);

  const mismatches = [];
  for (const [id, spec] of Object.entries(JUDGE_PROBLEMS)) {
    const opt = INTERVIEW[id]?.optimal;
    const specComp = spec.solution?.complexity;
    const isKnown = KNOWN_CASES.has(id);
    if (!opt || !specComp) {
      mismatches.push({ id, specComp: specComp ?? "(missing)", opt: opt ?? "(missing)", reason: "missing complexity" });
      continue;
    }
    const nOpt = normalizeComplexity(opt);
    const nSpec = normalizeComplexity(specComp);
    if (isKnown || (!nSpec.includes(nOpt) && !nOpt.includes(nSpec))) {
      mismatches.push({ id, specComp, opt, isKnown });
    }
  }
  return mismatches;
}

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  if (cmd === "build" || cmd === "check") {
    const { files, bruteFiles, errors } = readSolutionFiles();
    const { JUDGE_PROBLEMS } = await loadTs();
    const allFiles = [...files, ...bruteFiles];
    const bad = checkFiles(allFiles, errors, new Set(Object.keys(JUDGE_PROBLEMS)));
    if (cmd === "build") {
      if (bad.length) {
        console.error(`Solution problems (${bad.length}):\n${bad.map((b) => `  ${b}`).join("\n")}`);
        process.exit(1);
      }
      const out = renderGenerated(files, bruteFiles);
      const have = fs.existsSync(GENERATED_FILE) ? fs.readFileSync(GENERATED_FILE, "utf8") : "";
      if (have !== out) fs.writeFileSync(GENERATED_FILE, out);
      console.log(`Built ${files.length} solution files and ${bruteFiles.length} brute files into packages/shared/src/judge/generated/solutions.ts`);
      return;
    }
    if (!generatedIsCurrent()) bad.push("generated/solutions.ts is out of date. Run: pnpm solutions:build");
    if (bad.length) {
      console.error(`Solution problems (${bad.length}):\n${bad.map((b) => `  ${b}`).join("\n")}`);
      process.exit(1);
    }
    console.log(`Solutions OK: ${files.length} solutions, ${bruteFiles.length} brute files.`);
    return;
  }
  if (cmd === "audit") {
    const { JUDGE_PROBLEMS, INTERVIEW } = await loadTs();
    const mismatches = auditComplexity(JUDGE_PROBLEMS, INTERVIEW);
    console.log(`=== Solutions Audit: Complexity Alignment ===`);
    console.log(`Checked ${Object.keys(JUDGE_PROBLEMS).length} problems against interview walkthrough optimal complexity.`);
    if (!mismatches.length) {
      console.log("All problems match interview optimal complexity.");
      return;
    }
    console.log(`Found ${mismatches.length} potential mismatches/known cases:\n`);
    for (const m of mismatches) {
      const tag = m.isKnown ? " [KNOWN CASE from plan 0090]" : "";
      console.log(`- ${m.id}${tag}:\n    spec:        ${m.specComp}\n    walkthrough: ${m.opt}`);
    }
    return;
  }
  if (cmd === "status" || cmd === "todo") {
    const { SOLUTION_GROUP_IDS, groupIds, JUDGE_PROBLEMS, templateFor } = await loadTs();
    const { files, bruteFiles } = readSolutionFiles();

    // Parse frontmatter brute: same from interview files on disk if possible
    const itvDir = path.join(root, "packages/shared/content/interview");
    const interviewMeta = {};
    if (fs.existsSync(itvDir)) {
      for (const name of fs.readdirSync(itvDir)) {
        if (!name.endsWith(".md")) continue;
        const id = name.slice(0, -3);
        const text = fs.readFileSync(path.join(itvDir, name), "utf8");
        const m = text.match(/brute:\s*(\w+)/);
        if (m) interviewMeta[id] = { brute: m[1] };
      }
    }

    if (cmd === "status") {
      const group = rest.find((a, i) => !a.startsWith("-") && rest[i - 1] !== "--limit" && rest[i - 1] !== "--file");
      if (group && !SOLUTION_GROUP_IDS.includes(group)) {
        console.error(`Unknown group "${group}". Use one of: ${SOLUTION_GROUP_IDS.join(", ")}`);
        process.exit(2);
      }

      for (const g of group ? [group] : SOLUTION_GROUP_IDS) {
        const s = groupStatus(groupIds(g), files, bruteFiles, interviewMeta);
        const pct = (n) => `${n}/${s.total} (${Math.round((n / (s.total || 1)) * 100)}%)`;
        console.log(`group ${g}:`);
        console.log(`  optimal: java ${pct(s.java)}, python ${pct(s.python)}`);
        console.log(`  brute:   cpp ${pct(s.bruteCpp)}, java ${pct(s.bruteJava)}, python ${pct(s.brutePython)} (brute: same on ${s.bruteSame})`);
        if (group) {
          if (s.missingJava.length) console.log(`  missing java (${s.missingJava.length}): ${s.missingJava.join(", ")}`);
          if (s.missingPython.length) console.log(`  missing python (${s.missingPython.length}): ${s.missingPython.join(", ")}`);
          if (s.missingBrute.length) console.log(`  missing brute (${s.missingBrute.length}): ${s.missingBrute.slice(0, 10).join(", ")}${s.missingBrute.length > 10 ? "..." : ""}`);
        }
        if (s.skipStress.length) console.log(`  python skip-stress (${s.skipStress.length}): ${s.skipStress.join(", ")}`);
      }
      return;
    }

    // cmd === "todo"
    const fileIdx = rest.indexOf("--file");
    let targetIds = [];
    let label = "";

    if (fileIdx >= 0) {
      const fileName = rest[fileIdx + 1];
      if (!fileName) {
        console.error("--file requires a spec file path or name, e.g. problems-leetcode.ts");
        process.exit(2);
      }
      const specPath = path.isAbsolute(fileName)
        ? fileName
        : path.join(root, "packages/shared/src/judge", path.basename(fileName));
      if (!fs.existsSync(specPath)) {
        console.error(`Spec file not found: ${specPath}`);
        process.exit(2);
      }
      const specUrl = new URL(`file:///${specPath.replace(/\\/g, "/")}`).href;
      const mod = await import(specUrl);
      const specs = Object.values(mod).find((val) => Array.isArray(val) && val.length > 0 && val[0].id && val[0].fn);
      if (!specs) {
        console.error(`Could not find problem spec array in ${specPath}`);
        process.exit(2);
      }
      targetIds = specs.map((s) => s.id);
      label = path.basename(specPath);
    } else {
      const group = rest.find((a, i) => !a.startsWith("-") && rest[i - 1] !== "--limit" && rest[i - 1] !== "--file");
      if (!group || !SOLUTION_GROUP_IDS.includes(group)) {
        console.error("Usage: pnpm solutions:todo <group d|e|f> [--limit 10] OR pnpm solutions:todo --file <problems-x.ts> [--limit 10]");
        process.exit(2);
      }
      targetIds = groupIds(group);
      label = `Group ${group}`;
    }

    const li = rest.indexOf("--limit");
    const limit = li >= 0 ? Number(rest[li + 1]) : 10;
    if (!Number.isInteger(limit) || limit < 1) {
      console.error("--limit needs a positive whole number");
      process.exit(2);
    }

    const s = groupStatus(targetIds, files, bruteFiles, interviewMeta);
    // Problems missing either optimal files OR brute files (unless brute: same)
    const pendingIds = targetIds.filter((id) => {
      const isBruteSame = interviewMeta[id]?.brute === "same";
      const hasJava = files.some((f) => f.id === id && f.lang === "java");
      const hasPy = files.some((f) => f.id === id && f.lang === "python");
      const hasBcpp = bruteFiles.some((f) => f.id === id && f.lang === "cpp");
      const hasBjava = bruteFiles.some((f) => f.id === id && f.lang === "java");
      const hasBpy = bruteFiles.some((f) => f.id === id && f.lang === "python");
      if (!hasJava || !hasPy) return true;
      if (!isBruteSame && (!hasBcpp || !hasBjava || !hasBpy)) return true;
      return false;
    });

    const next = pendingIds.slice(0, limit);
    if (!next.length) {
      console.log(`${label} is complete (${targetIds.length} problems).`);
      return;
    }

    console.log(`${label}: ${pendingIds.length} of ${targetIds.length} problems still have missing files. Next ${next.length}:\n`);
    for (const id of next) {
      const spec = JUDGE_PROBLEMS[id];
      const isBruteSame = interviewMeta[id]?.brute === "same";
      const hasJava = files.some((f) => f.id === id && f.lang === "java");
      const hasPy = files.some((f) => f.id === id && f.lang === "python");
      const hasBcpp = bruteFiles.some((f) => f.id === id && f.lang === "cpp");
      const hasBjava = bruteFiles.some((f) => f.id === id && f.lang === "java");
      const hasBpy = bruteFiles.some((f) => f.id === id && f.lang === "python");

      const need = [];
      if (!hasJava) need.push(`${id}.java`);
      if (!hasPy) need.push(`${id}.py`);
      if (!isBruteSame) {
        if (!hasBcpp) need.push(`${id}.brute.cpp`);
        if (!hasBjava) need.push(`${id}.brute.java`);
        if (!hasBpy) need.push(`${id}.brute.py`);
      }
      console.log(`${"=".repeat(78)}\n${id}: ${spec?.title ?? id}\nWrite: ${need.join(", ")}${isBruteSame ? " (brute: same)" : ""}\n`);
    }
    return;
  }
  console.error("Usage: node scripts/solutions.mjs build | check | audit | status [group] | todo <group> [--file <spec>] [--limit N]");
  process.exit(2);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
